onClick:
{{
  Cloturer_Inventaire.run()
    .then(() => {
      showAlert('✅ Inventaire clôturé et stocks mis à jour !', 'success');

      // 1. On ferme le modal
      closeModal('Modal_cloture_inv');

      // 2. On rafraîchit la liste des inventaires
      return Get_Inventaires_Actifs.run();
    })
    .then(() => {
      // 3. On vide les tableaux pour nettoyer l'écran
      Get_Derniers_Scans.clear();
      Get_Non_Scannes.clear();
    })
    .catch((error) => {
      showAlert('Erreur lors de la clôture : ' + error.message, 'error');
    });
}}
